package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Set;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The events that only report figures: they never name a delegating steward. A SNAPSHOT is not
     *  one of them: it records the user's own change of the sheet's today. */
    private static final Set<String> FIGURES_ONLY = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;
    private final ObjectProvider<SettingService> settings;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<SettingService> settings) {
        this.file = Path.of(path);
        this.settings = settings;
    }

    /**
     * The record as written: a change made by a user acting as a steward by a delegation in force on
     * the sheet's today ends with for=<the steward who delegated>; a record that only reports figures
     * does not.
     */
    private String delegated(String entry) {
        String event = entry.split(" ", 2)[0];
        int sheetAt = entry.indexOf(" sheet=");
        int byAt = entry.indexOf(" by=");
        if (FIGURES_ONLY.contains(event) || sheetAt < 0 || byAt < sheetAt) {
            return entry;
        }
        String sheetId = entry.substring(sheetAt + " sheet=".length(), byAt);
        int byEnd = entry.indexOf(' ', byAt + " by=".length());
        String by = entry.substring(byAt + " by=".length(), byEnd < 0 ? entry.length() : byEnd);
        return settings.getObject().delegatedBy(sheetId, by).map(steward -> entry + " for=" + steward).orElse(entry);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing; outside a transaction it is appended at once.
     */
    public void recordOnCommit(String change) {
        String entry = delegated(change);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.holiday;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/holidays")
public class HolidayController {

    /** A holiday as the screen shows it. */
    public record HolidayView(Long id, LocalDate date) {
        static HolidayView of(Holiday holiday) {
            return new HolidayView(holiday.getId(), holiday.getDate());
        }
    }

    /** A holiday: its date. */
    public record HolidayRequest(@NotNull LocalDate date) {
    }

    private final HolidayService service;
    private final RollupService rollups;

    public HolidayController(HolidayService service, RollupService rollups) {
        this.service = service;
        this.rollups = rollups;
    }

    /** The sheet's holidays, the earliest first. */
    @GetMapping
    public List<HolidayView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId) {
        return service.list(sheetId.trim()).stream().map(HolidayView::of).toList();
    }

    /** Add a holiday to the sheet, then record the figures the due-bys it re-fixes moved. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public HolidayView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated HolidayRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return HolidayView.of(rollups.track(sheet, by, () -> service.add(sheet, by, request.date())));
    }

    /** A date already on the sheet's list is refused. */
    @ExceptionHandler({HolidayRefusedException.class, DataIntegrityViolationException.class})
    @ResponseStatus(HttpStatus.CONFLICT)
    public void refused() {
    }

    /** A date that is not a real yyyy-mm-dd date is refused. */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }
}
import { HttpClient } from '@angular/common/http';
import { Component, Injectable, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

export interface Holiday {
  id: number;
  /** The holiday (yyyy-mm-dd); unique on the sheet, it names the holiday's row. */
  date: string;
}

const DATE = /^\d{4}-\d{2}-\d{2}$/;

// The active sheet's holidays, the earliest first, re-read whenever a sheet is loaded.
@Injectable({ providedIn: 'root' })
export class HolidayStore {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly holidays = signal<Holiday[]>([]);

  constructor() {
    effect(() => {
      const sheet = this.session.sheetId();
      const load = this.session.loads();
      this.holidays.set([]);
      if (sheet) void this.read(sheet, load);
    });
  }

  /** Add a holiday to the active sheet; the server refuses a date already on its list. */
  async add(date: string): Promise<void> {
    const sheet = this.session.sheetId();
    if (!sheet) throw new Error('No sheet loaded.');
    const saved = await firstValueFrom(
      this.http.post<Holiday>(`/api/sheets/${encodeURIComponent(sheet)}/holidays`, { date }),
    );
    if (this.session.sheetId() !== sheet) return;
    this.holidays.update((list) =>
      [...list.filter((h) => h.id !== saved.id), saved].sort((a, b) => a.date.localeCompare(b.date)),
    );
  }

  private async read(sheet: string, load: number): Promise<void> {
    const list = await firstValueFrom(
      this.http.get<Holiday[]>(`/api/sheets/${encodeURIComponent(sheet)}/holidays`),
    );
    if (this.session.loads() !== load) return;
    this.holidays.set(list);
  }
}

// The sheet's holidays, which a claim's terms skip as non-business days when it is added, and the entry that
// adds one.
@Component({
  selector: 'app-holidays',
  template: `
    <section aria-labelledby="holidays-heading">
      <h2 id="holidays-heading">Holidays</h2>
      <form (submit)="submit($event)">
        <label for="holiday-date">Holiday</label>
        <input
          id="holiday-date"
          type="date"
          data-testid="holiday-date"
          [value]="date()"
          (input)="date.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="holiday-add">Add holiday</button>
        @if (error(); as message) {
          <p role="alert" data-testid="holiday-error">{{ message }}</p>
        }
      </form>
      <ul>
        @for (h of store.holidays(); track h.id) {
          <li [attr.data-testid]="'holiday-row-' + h.date">
            <span data-testid="holiday-row-date">{{ h.date }}</span>
          </li>
        }
      </ul>
    </section>
  `,
})
export class Holidays {
  protected readonly store = inject(HolidayStore);
  protected readonly date = signal('');
  protected readonly error = signal<string | null>(null);
  /** Whether a submit is waiting for its answer; a second submit meanwhile is dropped. */
  private readonly busy = signal(false);

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  /** Add the typed date as a holiday; a date already on the list is refused beside the entry. */
  protected async submit(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy()) return;
    this.error.set(null);
    const date = this.date().trim();
    if (!DATE.test(date)) {
      this.error.set('Type a date (yyyy-mm-dd) for the holiday.');
      return;
    }
    this.busy.set(true);
    try {
      await this.store.add(date);
    } catch {
      this.error.set(`The holiday ${date} could not be added: it may be on the list already.`);
    } finally {
      this.busy.set(false);
    }
  }
}
